CREATE PROCEDURE [dbo].[GetMaxSaleID]
AS
BEGIN
    SET NOCOUNT ON;

    -- Declarar variable para almacenar el resultado
    DECLARE @MaxSaleID INT;

    -- Obtener el valor máximo de SaleID
    SELECT @MaxSaleID = MAX(SaleID)
    FROM FusionSales;

    -- Si no hay registros, asignar 0 a @MaxSaleID
    IF @MaxSaleID IS NULL
        SET @MaxSaleID = 0;

    -- Retornar el resultado
    SELECT @MaxSaleID AS MaxSaleID;
END;

CREATE PROCEDURE [dbo].[InsertFusionSale]
    @SaleID INT,
    @PosNumber INT,
    @PumpNumber INT,
    @HoseNumber VARCHAR(2),
    @Amount DECIMAL(18,2),
    @PPU DECIMAL(18,5),
    @Volume DECIMAL(18,5),
    @FinalVolumeTotal DECIMAL(18,5),
    @InitialVolumeTotal DECIMAL(18,5),
    @PaymentType NVARCHAR(50),
    @PaymentInfo NVARCHAR(50),
    @CompensatedTemperature NVARCHAR(50),
    @ShiftID INT,
    @GradeNr INT,
    @PriceLevel INT,
    @TypeOfTransaction NVARCHAR(50),
    @DateOfTransaction NVARCHAR(50),
    @TimeOfTransaction NVARCHAR(50),
    @PresetAmount DECIMAL(18,2),
    @PaymentAlarm NVARCHAR(50),
    @ATCVO NVARCHAR(50),
    @AVGTM NVARCHAR(50),
    @ATCIVO NVARCHAR(50),
    @ATCFVO NVARCHAR(50),
    @IsInvoiced BIT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        IF NOT EXISTS (SELECT 1 FROM [FusionController].[dbo].[FusionSales] WITH (ROWLOCK) WHERE [SaleID] = @SaleID)
        BEGIN
            INSERT INTO [FusionController].[dbo].[FusionSales] (
                [SaleID],
                [PosNumber],
                [PumpNumber],
                [HoseNumber],
                [Amount],
                [PPU],
                [Volume],
                [FinalVolumeTotal],
                [InitialVolumeTotal],
                [PaymentType],
                [PaymentInfo],
                [CompensatedTemperature],
                [ShiftID],
                [GradeNr],
                [PriceLevel],
                [TypeOfTransaction],
                [DateOfTransaction],
                [TimeOfTransaction],
                [PresetAmount],
                [PaymentAlarm],
                [ATCVO],
                [AVGTM],
                [ATCIVO],
                [ATCFVO],
                [IsInvoiced],
                [Date]
            )
            VALUES (
                @SaleID,
                @PosNumber,
                @PumpNumber,
                @HoseNumber,
                @Amount,
                @PPU,
                @Volume,
                @FinalVolumeTotal,
                @InitialVolumeTotal,
                @PaymentType,
                @PaymentInfo,
                @CompensatedTemperature,
                @ShiftID,
                @GradeNr,
                @PriceLevel,
                @TypeOfTransaction,
                @DateOfTransaction,
                @TimeOfTransaction,
                @PresetAmount,
                @PaymentAlarm,
                @ATCVO,
                @AVGTM,
                @ATCIVO,
                @ATCFVO,
                @IsInvoiced,
                GETDATE()
            );

            COMMIT TRANSACTION;
            SELECT 'Success' AS Status, 'Record inserted successfully' AS Message;
        END
        ELSE
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT 'Error' AS Status, 'SaleID already exists' AS Message;
        END
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;
        SELECT 'Error' AS Status, ERROR_MESSAGE() AS Message;
    END CATCH
END

CREATE PROCEDURE [dbo].[ReversarTransaccion]
    @SaleID INT
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE FusionSales
    SET IsInvoiced = 0,  -- False en SQL Server es 0
        Date = GETDATE()
    WHERE SaleID = @SaleID;
END;

CREATE PROCEDURE [dbo].[SP_FusionSales_Consolidado]
    @ShiftIDs NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    -- Tabla temporal forzando el Collation por defecto de la base de datos
    IF OBJECT_ID('tempdb..#ShiftIDTable') IS NOT NULL DROP TABLE #ShiftIDTable;
    CREATE TABLE #ShiftIDTable (
        ID NVARCHAR(50) COLLATE DATABASE_DEFAULT
    );

    -- Separar los IDs (Split function logic)
    DECLARE @Pos INT;
    DECLARE @NextPos INT;
    DECLARE @ID NVARCHAR(50);

    SET @Pos = 1;
    WHILE @Pos <= LEN(@ShiftIDs) + 1
    BEGIN
        SET @NextPos = CHARINDEX(',', @ShiftIDs, @Pos);
        IF @NextPos = 0 SET @NextPos = LEN(@ShiftIDs) + 1;
        
        SET @ID = LTRIM(RTRIM(SUBSTRING(@ShiftIDs, @Pos, @NextPos - @Pos)));
        IF LEN(@ID) > 0
            INSERT INTO #ShiftIDTable (ID) VALUES (@ID);
            
        SET @Pos = @NextPos + 1;
    END

    -- Consulta que fuerza la comparación con COLLATE DATABASE_DEFAULT para evitar el conflicto
    SELECT 
        PumpNumber AS Bomba,
        HoseNumber AS Manguera,
        MIN(InitialVolumeTotal) AS [Vol. Inicial],
        MAX(FinalVolumeTotal) AS [Vol. Final],
        SUM(Volume) AS [Vol. Total],
        SUM(Amount) AS [Monto Total],
        MAX(PPU) AS Precio,
        CAST(NULL AS NVARCHAR(100)) AS GradeNames
    FROM dbo.FusionSales
    WHERE ShiftID COLLATE DATABASE_DEFAULT IN (SELECT ID FROM #ShiftIDTable)
    GROUP BY PumpNumber, HoseNumber
    ORDER BY PumpNumber, HoseNumber;

    DROP TABLE #ShiftIDTable;
END

CREATE PROCEDURE [dbo].[sp_InsertFusionSaleVOX]
    @vox_sale_id INT,
    @pump SMALLINT,
    @hose SMALLINT,
    @amount DECIMAL(18,2),
    @ppu DECIMAL(18,5),
    @volume DECIMAL(18,5),
    @total_volume_final DECIMAL(18,5),
    @total_volume_init DECIMAL(18,5),
    @shift_id VARCHAR(50),
    @level SMALLINT,
    @product SMALLINT,
    @fecha DATE,
    @hora TIME,
    @invoiced BIT
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @fechaHora DATETIME = DATEADD(HOUR, -12, CAST(@fecha AS DATETIME) + CAST(@hora AS DATETIME));
    DECLARE @fechaCorregida DATE = CAST(@fechaHora AS DATE);
    DECLARE @horaCorregida TIME = CAST(@fechaHora AS TIME);

    INSERT INTO [dbo].[FusionSales] (
        SaleID,
        PosNumber,
        PumpNumber,
        HoseNumber,
        Amount,
        PPU,
        Volume,
        FinalVolumeTotal,
        InitialVolumeTotal,
        ShiftID,
        PriceLevel,
        GradeNr,
        DateOfTransaction,
        TimeOfTransaction,
        IsInvoiced,
        [Date]
    )
    VALUES (
        @vox_sale_id,              -- SaleID
        99,                        -- PosNumber fijo
        @pump,                     -- PumpNumber
        CAST(@hose AS VARCHAR(2)), -- HoseNumber
        @amount / 10,             -- Amount dividido entre 100
        @ppu / 100,                -- PPU dividido entre 100
        @volume / 100,             -- Volume dividido entre 100
        @total_volume_final / 100, -- FinalVolumeTotal dividido entre 100
        @total_volume_init / 100,  -- InitialVolumeTotal dividido entre 100
        @shift_id,                 -- ShiftID
        @level,                    -- PriceLevel
        @product,                  -- GradeNr
        CONVERT(NVARCHAR(50), @fechaCorregida, 23),     -- Fecha corregida (YYYY-MM-DD)
        CONVERT(NVARCHAR(50), @horaCorregida, 8),       -- Hora corregida (HH:MM:SS)
        @invoiced,                 -- IsInvoiced
        GETDATE()                  -- Date = momento de la copia
    );
END

CREATE PROCEDURE [dbo].[UpdateIsInvoiced]
    @IdSale INT,
	@PosNumber int
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE [FusionSales]
    SET [IsInvoiced] = 1, PosNumber=@PosNumber
    WHERE [IsInvoiced] = 0 AND SaleID = @IdSale;

    -- Opcional: Retornar el número de filas afectadas
    RETURN @@ROWCOUNT;
END;
